const u=[{id:"low",label:"Sezon i ulët",labelEn:"Low Season",months:[1,2,11],multiplier:.85,badgeColor:"bg-blue-100 text-blue-700 border-blue-200",description:"Çmimet janë 15% më të ulëta gjatë muajve janar, shkurt dhe nëntor.",emoji:"❄️"},{id:"normal",label:"Sezon normal",labelEn:"Regular Season",months:[3,4,10,12],multiplier:1,badgeColor:"bg-neutral-100 text-neutral-600 border-neutral-200",description:"Çmimet standarde pa ndonjë shtesa ose zbritje sezonale.",emoji:"🌤️"},{id:"high",label:"Sezon i lartë",labelEn:"High Season",months:[5,6,9],multiplier:1.2,badgeColor:"bg-amber-100 text-amber-700 border-amber-200",description:"Kërkesa e lartë në maj, qershor dhe shtator: +20% mbi çmimin bazë.",emoji:"☀️"},{id:"peak",label:"Sezon kulminant",labelEn:"Peak Season",months:[7,8],multiplier:1.4,badgeColor:"bg-orange-100 text-orange-700 border-orange-200",description:"Korrik dhe gusht janë muajt me kërkesën më të lartë: +40% mbi çmimin bazë.",emoji:"🔥"}];function d(e=new Date){const t=e.getMonth()+1;return u.find(n=>n.months.includes(t))??u[1]}function j(e,t=new Date){const n=Number(e);if(!Number.isFinite(n))return 0;const a=d(t);return Math.round(n*a.multiplier*100)/100}function S(e,t,n){const a=[],s=Number.isFinite(Number(e))?Number(e):0,o=new Date(t);o.setHours(0,0,0,0);const b=new Date(n);b.setHours(0,0,0,0);const c=24*60*60*1e3,g=Math.max(1,Math.ceil((b.getTime()-o.getTime())/c));for(let i=0;i<g;i+=1){const r=d(o),m=Math.round(s*r.multiplier*100)/100,l=a.find(p=>p.season.id===r.id);l?(l.days+=1,l.subtotal=Math.round((l.subtotal+m)*100)/100):a.push({season:r,days:1,pricePerDay:m,subtotal:m}),o.setDate(o.getDate()+1)}const h=a.reduce((i,r)=>i+r.subtotal,0);return{total:Math.round(h*100)/100,breakdown:a}}function D(e,t){const{breakdown:n}=S(1,e,t);return n.length===0?u[1]:n.reduce((a,s)=>a.days>=s.days?a:s).season}function f(e){return u.map(t=>({season:t,pricePerDay:Math.round(e*t.multiplier*100)/100}))}export{d as a,D as b,S as c,f as d,j as g};
